CREATE TABLE schema_version (singleton INTEGER PRIMARY KEY CHECK (singleton = 1), version INTEGER NOT NULL CHECK (version > 0)); INSERT INTO schema_version (singleton, version) VALUES (1, 1); CREATE TABLE writer_leases (service_id BLOB PRIMARY KEY CHECK (typeof(service_id) = 'blob' AND length(service_id) = 32), epoch INTEGER NOT NULL CHECK (epoch > 0), owner BLOB CHECK (owner IS NULL OR (typeof(owner) = 'blob' AND length(owner) = 16))) WITHOUT ROWID; CREATE TABLE journal_transactions (transaction_id BLOB PRIMARY KEY CHECK (typeof(transaction_id) = 'blob' AND length(transaction_id) = 16), service_id BLOB NOT NULL CHECK (typeof(service_id) = 'blob' AND length(service_id) = 32), kind TEXT NOT NULL CHECK (kind IN ('bootstrap', 'adopt', 'upgrade')), state TEXT NOT NULL CHECK (state IN ('active', 'degraded', 'failed', 'succeeded')), runtime TEXT NOT NULL CHECK (runtime IN ('docker', 'podman', 'containerd')), source_digest BLOB NOT NULL CHECK (typeof(source_digest) = 'blob' AND length(source_digest) = 32 AND source_digest != zeroblob(32)), effective_digest BLOB NOT NULL CHECK (typeof(effective_digest) = 'blob' AND length(effective_digest) = 32 AND effective_digest != zeroblob(32)), execution_digest BLOB NOT NULL CHECK (typeof(execution_digest) = 'blob' AND length(execution_digest) = 32 AND execution_digest != zeroblob(32)), base_transaction_id BLOB CHECK (base_transaction_id IS NULL OR (typeof(base_transaction_id) = 'blob' AND length(base_transaction_id) = 16)), predecessor_workload_id TEXT CHECK (predecessor_workload_id IS NULL OR (typeof(predecessor_workload_id) = 'text' AND length(CAST(predecessor_workload_id AS BLOB)) BETWEEN 1 AND 256 AND instr(predecessor_workload_id, char(0)) = 0)), UNIQUE (transaction_id, service_id), FOREIGN KEY (service_id) REFERENCES writer_leases(service_id), FOREIGN KEY (base_transaction_id, service_id) REFERENCES journal_transactions(transaction_id, service_id), CHECK ((kind = 'bootstrap' AND base_transaction_id IS NULL AND predecessor_workload_id IS NULL) OR (kind = 'adopt' AND base_transaction_id IS NULL AND predecessor_workload_id IS NOT NULL) OR (kind = 'upgrade' AND base_transaction_id IS NOT NULL AND predecessor_workload_id IS NOT NULL))) WITHOUT ROWID; CREATE UNIQUE INDEX journal_one_unresolved_transaction_per_service ON journal_transactions(service_id) WHERE state IN ('active', 'degraded'); CREATE TABLE journal_actions (transaction_id BLOB NOT NULL CHECK (typeof(transaction_id) = 'blob' AND length(transaction_id) = 16), sequence INTEGER NOT NULL CHECK (typeof(sequence) = 'integer' AND sequence > 0), kind TEXT NOT NULL CHECK (typeof(kind) = 'text' AND length(kind) BETWEEN 1 AND 64 AND substr(kind, 1, 1) GLOB '[a-z0-9]' AND kind NOT GLOB '*[^a-z0-9._-]*'), state TEXT NOT NULL CHECK (state IN ('intent', 'effect_outcome_unknown', 'completed')), intent_digest BLOB NOT NULL CHECK (typeof(intent_digest) = 'blob' AND length(intent_digest) = 32), postcondition_digest BLOB, PRIMARY KEY (transaction_id, sequence), FOREIGN KEY (transaction_id) REFERENCES journal_transactions(transaction_id) ON DELETE CASCADE, CHECK ((state = 'completed' AND typeof(postcondition_digest) = 'blob' AND length(postcondition_digest) = 32) OR (state != 'completed' AND postcondition_digest IS NULL))) WITHOUT ROWID; CREATE TABLE applied_services (service_id BLOB PRIMARY KEY CHECK (typeof(service_id) = 'blob' AND length(service_id) = 32), transaction_id BLOB NOT NULL UNIQUE CHECK (typeof(transaction_id) = 'blob' AND length(transaction_id) = 16), workload_id TEXT NOT NULL CHECK (typeof(workload_id) = 'text' AND length(CAST(workload_id AS BLOB)) BETWEEN 1 AND 256 AND instr(workload_id, char(0)) = 0), configuration_digest BLOB NOT NULL CHECK (typeof(configuration_digest) = 'blob' AND length(configuration_digest) = 32 AND configuration_digest != zeroblob(32)), storage_digest BLOB NOT NULL CHECK (typeof(storage_digest) = 'blob' AND length(storage_digest) = 32 AND storage_digest != zeroblob(32)), reference_digest BLOB NOT NULL CHECK (typeof(reference_digest) = 'blob' AND length(reference_digest) = 32 AND reference_digest != zeroblob(32)), platform_manifest_digest BLOB NOT NULL CHECK (typeof(platform_manifest_digest) = 'blob' AND length(platform_manifest_digest) = 32 AND platform_manifest_digest != zeroblob(32)), image_config_digest BLOB NOT NULL CHECK (typeof(image_config_digest) = 'blob' AND length(image_config_digest) = 32 AND image_config_digest != zeroblob(32)), FOREIGN KEY (service_id) REFERENCES writer_leases(service_id), FOREIGN KEY (transaction_id, service_id) REFERENCES journal_transactions(transaction_id, service_id)) WITHOUT ROWID; CREATE TABLE workload_backups (transaction_id BLOB PRIMARY KEY CHECK (typeof(transaction_id) = 'blob' AND length(transaction_id) = 16), service_id BLOB NOT NULL CHECK (typeof(service_id) = 'blob' AND length(service_id) = 32), manifest_path TEXT NOT NULL CHECK (typeof(manifest_path) = 'text' AND manifest_path = lower(hex(transaction_id)) || '/manifest.json'), manifest_digest BLOB NOT NULL CHECK (typeof(manifest_digest) = 'blob' AND length(manifest_digest) = 32 AND manifest_digest != zeroblob(32)), created_unix INTEGER NOT NULL CHECK (typeof(created_unix) = 'integer' AND created_unix > 0), FOREIGN KEY (transaction_id, service_id) REFERENCES journal_transactions(transaction_id, service_id)) WITHOUT ROWID;
